拼接目录链接
{{baseUrl}}##(.*)www(.*)read(.*)##$1m$2novel/list$31.html
拼接目录链接<js>
base="https://www.po18.xyz/read/";
try{
$=result.match(/(\d+),(\d+)\)/)
url=base+$[2]+"/"+$[1]+"/";
}catch(error){
	try{
$=result.match(/(\d+)\/(\d+)\/$/)
url=base+$[1]+"/"+$[2]+"/";
}catch(anotherError){
	url="。。";
}
}
url;
</js>
目录列表顺序规则
*:matches(章节列表)~dd a
@js:
txt=`$(result)`.replace(/".*?(\d+)(\/|,.*?)"/g,"$1/").split("\n").sort();
目录列表顺序规则
<js>
a=java.getElements('//dt[@id="chapter_list"] /following-sibling:dd/a');
for(i=0,list=[];i<a.length;i+=3){
if(a[i+2]){list.push(a[i+2])}
if(a[i+1]){list.push(a[i+1])}
if(a[i]){list.push(a[i])}
}
list
</js>

