if (src.match(/data\-x/)) {
  result.sort((a, b) => a.attr("data-x") - b.attr("data-x"));
  result.select("a");
} else {
  result = result.select("a")
  try {
    eval(src.match(/var originalOrder = \[.*\];/)[0])
    list = []
    for (i in result) {
      list[originalOrder[i]] = result[i]
    }
    list
  } catch (err) {
    result;
  }
}
</js>

